UPDATE node_instance
SET state = 'FAILED', result = 'timeout', time_out = 1, finished_at = NOW(), updated_at = NOW()
WHERE id = #{id} AND state = 'RUNNING' AND started_at < #{deadline}

UPDATE node_instance
SET state = 'PENDING', result = NULL, time_out = 0, started_at = NULL, finished_at = NULL, updated_at = NOW()
WHERE task_id = #{taskId}
